@Override
  public void applyEffectTick(LivingEntity target, int level) {
    // attribute to player kill
    LivingEntity lastAttacker = target.getLastHurtMob();
    DamageSource source = TinkerDamageTypes.source(target.level().registryAccess(), TinkerDamageTypes.BLEEDING, lastAttacker);

    // perform damage
    int hurtResistantTime = target.invulnerableTime;
    ToolAttackUtil.attackEntitySecondary(source, 1, target, target, true);
    target.invulnerableTime = hurtResistantTime;

    // damage particles
    if (target.level() instanceof ServerLevel serverLevel) {
      serverLevel.sendParticles(ParticleTypes.DAMAGE_INDICATOR, target.getX(), target.getY(0.5), target.getZ(), 1, 0.1, 0, 0.1, 0.2);
    }
  }

@Override
  public boolean isDurationEffectTick(int tick, int level) {
    // every half second
    return tick > 0 && tick % 20 == 0;
  }

@Override
  public void afterMeleeHit(IToolStackView tool, ModifierEntry modifier, ToolAttackContext context, float damageDealt) {
    // 50% chance of applying
    LivingEntity target = context.getLivingTarget();
    if (target != null && context.isFullyCharged() && target.isAlive()) {
      // set entity so the potion is attributed as a player kill
      target.setLastHurtMob(context.getAttacker());
      applyEffect(tool, context.getAttacker(), target, modifier.getLevel(), context.getSlotType());
    }
  }

private static void applyEffect(IToolStackView tool, @Nullable LivingEntity holder, LivingEntity target, int level, @Nullable EquipmentSlot slot) {
    // determine looting
    int looting = 0;
    DamageSource source = CombatHelper.damageSource(TinkerDamageTypes.BLEEDING, target);
    if (holder != null) {
      LootingContext context = new LootingContext(holder, target, source, slot);
      // fetch slot looting for the melee hook
      looting = LootingModifierHook.getLooting(tool, context, looting);
      // fetch armor looting
      looting = ArmorLootingModifierHook.getLooting(null, context, looting);
    }

    // 81 ticks will do about 4 damage
    applyEffect(target, level, looting, holder);
  }

private static void applyEffect(LivingEntity target, int level, int looting, @Nullable Entity cause) {
    int duration = level * 2 * 20;
    MobEffectInstance existing = target.getEffect(TinkerEffects.bleeding.get());
    if (existing != null && existing.getAmplifier() == looting) {
      duration += existing.getDuration();
    } else {
      // add a small delay so first damage happens in about a second
      // skip when already present so we continue on the same clock and don't repeat a damage
      duration += 19;
    }
    target.addEffect(new MobEffectInstance(TinkerEffects.bleeding.get(), duration, looting), cause);
  }

@Override
  protected void registerHooks(Builder hookBuilder) {
    hookBuilder.addHook(this, ModifierHooks.PROJECTILE_HIT, ModifierHooks.MELEE_HIT, ModifierHooks.MONSTER_MELEE_HIT, ModifierHooks.ON_ATTACKED);
  }

public static boolean performAttack(IToolStackView tool, ToolAttackContext context) {
    // moved damage calculation, knockback, and cooldown to ToolAttackUtil.Builder
    // missing: enchantment modifiers, we handle modifiers instead

    // calculate conditional damage from modifiers
    float baseDamage = context.getBaseDamage();
    float damage = baseDamage;
    List<ModifierEntry> modifiers = tool.getModifierList();
    for (ModifierEntry entry : modifiers) {
      damage = entry.getHook(ModifierHooks.MELEE_DAMAGE).getMeleeDamage(tool, entry, context, baseDamage, damage);
    }
    // no damage? do nothing
    if (damage <= 0) {
      return false;
    }
    // checked immediately in case anything else changes damage
    boolean isMagic = damage > baseDamage;

    // knockback moved lower

    // apply critical damage boost
    float criticalModifier = context.getCriticalModifier();
    if (criticalModifier != 1) {
      damage += baseDamage * (criticalModifier - 1);
    }

    // removed: sword check hook, replaced by weapon callback
    // removed: fire aspect check, replaced by before damage lower

    // apply cutoff and cooldown, store if damage was above base for magic particles
    float cooldown = context.getCooldown();
    if (cooldown < 1) {
      damage *= (0.2f + cooldown * cooldown * 0.8f);
    }

    // track original health and motion before attack
    // Vec3 originalTargetMotion = targetEntity.getDeltaMovement();
    float oldHealth = 0.0F;
    LivingEntity targetLiving = context.getLivingTarget();
    if (targetLiving != null) {
      oldHealth = targetLiving.getHealth();
    }

    // removed: vanilla knockback enchant support
    // changed: knockback halved for simplicity

    // apply modifier knockback and special effects
    float baseKnockback = context.getBaseKnockback();
    float knockback = baseKnockback;
    for (ModifierEntry entry : modifiers) {
      knockback = entry.getHook(ModifierHooks.MELEE_HIT).beforeMeleeHit(tool, entry, context, damage, baseKnockback, knockback);
    }

    // set hand for proper looting context
    LivingEntity attackerLiving = context.getAttacker();
    EquipmentSlot sourceSlot = context.getSlotType();
    ModifierLootingHandler.setLootingSlot(attackerLiving, sourceSlot);

    // if knockback is below the vanilla amount, we need to prevent knockback, the remainder will be applied later
    AttributeInstance knockbackModifier = null;
    if (knockback < 0.4f) {
      knockbackModifier = disableKnockback(targetLiving);
    } else if (targetLiving != null) {
      // we will apply 0.4 of the knockback in the attack hook, need to apply the remainder ourself
      knockback -= 0.4f;
    }

    ///////////////////
    // actual attack //
    ///////////////////

    // removed: sword special attack check and logic, replaced by this
    Entity targetEntity = context.getTarget();
    boolean didHit = targetEntity.hurt(context.makeDamageSource(), damage);

    // reset hand to make sure we don't mess with vanilla tools
    ModifierLootingHandler.setLootingSlot(attackerLiving, EquipmentSlot.MAINHAND);
    // reset knockback if needed
    enableKnockback(knockbackModifier);

    // if we failed to hit, fire failure hooks
    // alternatively, if we cannot hit this target, we are supposed to return true for the sake of special casing endermen,
    Level level = context.getLevel();
    boolean isExtraAttack = context.isExtraAttack();
    Projectile projectile = context.getProjectile();
    if (!didHit || projectile != null && !TinkerEffects.canHitWithProjectile(targetLiving)) {
      if (!isExtraAttack) {
        level.playSound(null, attackerLiving.getX(), attackerLiving.getY(), attackerLiving.getZ(), SoundEvents.PLAYER_ATTACK_NODAMAGE, attackerLiving.getSoundSource(), 1.0F, 1.0F);
      }
      // alert modifiers nothing was hit, mainly used for fiery
      for (ModifierEntry entry : modifiers) {
        entry.getHook(ModifierHooks.MELEE_HIT).failedMeleeHit(tool, entry, context, damage);
      }
      return false;
    }

    // post melee hook - TODO: should this be lower?
    tool.getHook(ToolHooks.MELEE_HIT).afterMeleeHit(tool, context, damage);

    // determine damage actually dealt
    float damageDealt = damage;
    if (targetLiving != null) {
      damageDealt = oldHealth - targetLiving.getHealth();
    }

    // apply knockback
    if (knockback > 0) {
      if (targetLiving != null) {
        targetLiving.knockback(knockback, Mth.sin(attackerLiving.getYRot() * DEGREE_TO_RADIANS), -Mth.cos(attackerLiving.getYRot() * DEGREE_TO_RADIANS));
      } else {
        targetEntity.push(-Mth.sin(attackerLiving.getYRot() * DEGREE_TO_RADIANS) * knockback, 0.1d, Mth.cos(attackerLiving.getYRot() * DEGREE_TO_RADIANS) * knockback);
      }
      attackerLiving.setDeltaMovement(attackerLiving.getDeltaMovement().multiply(0.6D, 1.0D, 0.6D));
      attackerLiving.setSprinting(false);
    }

    // removed: sword sweep attack, handled above

    // apply velocity change to players if needed
    if (targetEntity.hurtMarked && targetEntity instanceof ServerPlayer serverPlayer) {
      serverPlayer.connection.send(new ClientboundSetEntityMotionPacket(targetEntity));
      targetEntity.hurtMarked = false;
      // TODO: why was this needed before? targetEntity.setDeltaMovement(originalTargetMotion);
    }

    // play sound effects and particles

    Player attackerPlayer = context.getPlayerAttacker();
    if (attackerPlayer != null) {
      // particles
      if (criticalModifier > 1) {
        attackerPlayer.crit(targetEntity);
      }
      if (isMagic) {
        attackerPlayer.magicCrit(targetEntity);
      }
      // sounds
      level.playSound(null, attackerLiving.getX(), attackerLiving.getY(), attackerLiving.getZ(), context.getSound(), attackerLiving.getSoundSource(), 1.0F, 1.0F);
    }
    if (damageDealt > 2.0F && level instanceof ServerLevel server) {
      int particleCount = (int)(damageDealt * 0.5f);
      server.sendParticles(ParticleTypes.DAMAGE_INDICATOR, targetEntity.getX(), targetEntity.getY(0.5), targetEntity.getZ(), particleCount, 0.1, 0, 0.1, 0.2);
    }

    // deal attacker thorns damage
    attackerLiving.setLastHurtMob(targetEntity);
    if (targetLiving != null) {
      EnchantmentHelper.doPostHurtEffects(targetLiving, attackerLiving);
    }

    // apply modifier effects
    // removed: bane of arthropods hook, replaced by this
    for (ModifierEntry entry : modifiers) {
      entry.getHook(ModifierHooks.MELEE_HIT).afterMeleeHit(tool, entry, context, damageDealt);
    }

    // hurt resistance adjustment for high speed weapons
    float speed = tool.getStats().get(ToolStats.ATTACK_SPEED);
    int time = Math.round(20f / speed);
    if (time < targetEntity.invulnerableTime) {
      targetEntity.invulnerableTime = (targetEntity.invulnerableTime + time) / 2;
    }

    // final attack hooks
    if (attackerPlayer != null) {
      if (targetLiving != null) {
        if (!level.isClientSide && !isExtraAttack) {
          ItemStack held = attackerLiving.getItemBySlot(sourceSlot);
          if (!held.isEmpty()) {
            held.hurtEnemy(targetLiving, attackerPlayer);
          }
        }
        attackerPlayer.awardStat(Stats.DAMAGE_DEALT, Math.round(damageDealt * 10.0F));
      }
      // removed: fire damage, handled in modifier hook above
      if (projectile == null) {
        attackerPlayer.causeFoodExhaustion(0.1F);
      }

      // add usage stat
      if (!isExtraAttack && projectile == null) {
        attackerPlayer.awardStat(Stats.ITEM_USED.get(tool.getItem()));
      }
    }

    // damage the tool
    if (!tool.hasTag(TinkerTags.Items.UNARMED)) {
      int durabilityLost = targetLiving != null ? 1 : 0;
      if (!tool.hasTag(TinkerTags.Items.MELEE_PRIMARY)) {
        durabilityLost *= 2;
      }
      // don't do the full damage animation for broken projectiles as it's not next to you, so that's weird
      if (projectile != null) {
        ToolDamageUtil.damage(tool, durabilityLost, attackerLiving, attackerLiving.getItemBySlot(sourceSlot));
      } else {
        ToolDamageUtil.damageAnimated(tool, durabilityLost, attackerLiving, sourceSlot);
      }
    }

    return true;
  }

public static boolean attackEntity(IToolStackView tool, Player attacker, Entity target) {
    if (!canPerformAttack(tool)) {
      return false;
    }
    if (isAttackable(attacker, target)) {
      performAttack(tool, ToolAttackContext.attacker(attacker).target(target).defaultCooldown().applyAttributes().build());
    }
    return true;
  }

static boolean leftClickEntity(ItemStack stack, Player player, Entity target) {
    ToolStack tool = ToolStack.from(stack);
    boolean noMelee = meleeDisabled(tool);
    if (stack.is(TinkerTags.Items.INTERACTABLE_LEFT)) {
      if (!player.getCooldowns().isOnCooldown(stack.getItem())) {
        List<ModifierEntry> modifiers = tool.getModifierList();
        // TODO: should this be in the event?
        for (ModifierEntry entry : modifiers) {
          if (entry.getHook(ModifierHooks.ENTITY_INTERACT).beforeEntityUse(tool, entry, player, target, InteractionHand.MAIN_HAND, InteractionSource.LEFT_CLICK).consumesAction()) {
            return true;
          }
        }
        if (target instanceof LivingEntity living) {
          for (ModifierEntry entry : modifiers) {
            if (entry.getHook(ModifierHooks.ENTITY_INTERACT).afterEntityUse(tool, entry, player, living, InteractionHand.MAIN_HAND, InteractionSource.LEFT_CLICK).consumesAction()) {
              return true;
            }
          }
        }
        // if melee attacks are disabled, we don't actually end up running right click hooks so run them here
        // also run the hook if we are not a melee weapon, as we don't need to bother with the 1 damage hit then
        if (noMelee || !tool.hasTag(TinkerTags.Items.MELEE)) {
          for (ModifierEntry entry : modifiers) {
            if (entry.getHook(ModifierHooks.GENERAL_INTERACT).onToolUse(tool, entry, player, InteractionHand.MAIN_HAND, InteractionSource.LEFT_CLICK).consumesAction()) {
              return true;
            }
          }
        }
      }
    }
    // block vanilla left click when melee is disabled, not just our left click
    // block even on cooldown
    if (noMelee) {
      // when you fail to damage a target, squeak
      player.playSound(Sounds.TOY_SQUEAK.getSound());
      return true;
    }
    // no left click modifiers? fallback to standard attack
    return ToolAttackUtil.attackEntity(tool, player, target);
  }

@Override
  public boolean onLeftClickEntity(ItemStack stack, Player player, Entity target) {
    return stack.getCount() > 1 || EntityInteractionModifierHook.leftClickEntity(stack, player, target);
  }

@SuppressWarnings("UnusedReturnValue")
  public static boolean attackEntitySecondary(DamageSource source, float damage, Entity target, @Nullable LivingEntity living, boolean noKnockback) {
    AttributeInstance knockbackResistance = null;
    // prevent knockback in secondary attacks, if requested
    if (noKnockback) {
      knockbackResistance = disableKnockback(living);
    }

    // hurt the target, bypassing invulnerability
    boolean hit = hurtNoInvulnerableTime(target, living, source, damage);

    // remove no knockback marker
    if (noKnockback) {
      enableKnockback(knockbackResistance);
    }

    return hit;
  }

public static boolean hurtNoInvulnerableTime(Entity target, @Nullable LivingEntity living, DamageSource source, float damage) {
    // store last damage before secondary attack
    float oldLastDamage = living == null ? 0 : living.lastHurt;

    // set hurt resistance time to 0 because we always want to deal damage in traits
    int lastInvulnerableTime = target.invulnerableTime;
    target.invulnerableTime = 0;
    boolean hit = target.hurt(source, damage);
    // reset to the old time so bows work right
    target.invulnerableTime = lastInvulnerableTime;
    // set total received damage, important for AI and stuff
    if (living != null) {
      living.lastHurt += oldLastDamage;
    }
    return hit;
  }

public static DamageSource source(RegistryAccess access, ResourceKey<DamageType> type, @Nullable Entity entity) {
    return source(access, type, entity, entity);
  }

public static DamageSource source(RegistryAccess access, ResourceKey<DamageType> type, @Nullable Entity direct, @Nullable Entity causing) {
    return new DamageSource(access.registryOrThrow(Registries.DAMAGE_TYPE).getHolderOrThrow(type), direct, causing);
  }

public static boolean stopArmorInteract(Player player, EquipmentSlot slotType) {
    if (!player.isSpectator()) {
      ItemStack helmet = player.getItemBySlot(slotType);
      if (helmet.is(TinkerTags.Items.ARMOR)) {
        ToolStack tool = ToolStack.from(helmet);
        // fetch interaction data if present
        int chargeTime = 0;
        ModifierEntry activeModifier = ModifierEntry.EMPTY;
        TinkerDataCapability.Holder data = TinkerDataCapability.getData(player);
        if (data != null) {
          Map<EquipmentSlot,ArmorInteractData> interactMap = data.get(INTERACT_KEY);
          if (interactMap != null) {
            ArmorInteractData interactData = interactMap.remove(slotType);
            if (interactData != null) {
              activeModifier = tool.getModifier(interactData.modifier);
              chargeTime = player.tickCount - interactData.startTime;
            }
          }
        }
        // run modifier hook for stop interact
        // TODO 1.21: consider only running hook on the active modifier
        for (ModifierEntry entry : tool.getModifierList()) {
          entry.getHook(ModifierHooks.ARMOR_INTERACT).stopInteract(tool, entry, player, slotType, chargeTime, activeModifier);
        }
        // cleanup drawtime on the tool
        GeneralInteractionModifierHook.finishUsing(tool);
        return true;
      }
    }
    return false;
  }

public static boolean startArmorInteract(Player player, EquipmentSlot slotType, TooltipKey modifierKey) {
    if (!player.isSpectator()) {
      ItemStack helmet = player.getItemBySlot(slotType);
      if (helmet.is(TinkerTags.Items.ARMOR)) {
        ToolStack tool = ToolStack.from(helmet);
        for (ModifierEntry entry : tool.getModifierList()) {
          if (entry.getHook(ModifierHooks.ARMOR_INTERACT).startInteract(tool, entry, player, slotType, modifierKey)) {
            // store data so we know when interaction started
            TinkerDataCapability.Holder data = TinkerDataCapability.getData(player);
            if (data != null) {
              data.computeIfAbsent(INTERACT_KEY).put(slotType, new ArmorInteractData(entry.getId(), player.tickCount));
            }
            break;
          }
        }
        return true;
      }
    }
    return false;
  }

private static void handleKeyBindings(PlayerTickEvent event) {
    Minecraft minecraft = Minecraft.getInstance();
    if (minecraft.player != null && minecraft.player == event.player && event.phase == Phase.START && event.side == LogicalSide.CLIENT && !minecraft.player.isSpectator()) {

      // jumping in mid air for double jump
      // ensure we pressed the key since the last tick, holding should not use all your jumps at once
      boolean isJumping = minecraft.options.keyJump.isDown();
      if (!wasJumping && isJumping) {
        if (TinkerEffects.antigravity.get().antigravityJump(event.player)) {
          TinkerNetwork.getInstance().sendToServer(TinkerControlPacket.ANTIGRAVITY_JUMP);
        }
        else if (DoubleJumpHandler.extraJump(event.player)) {
          TinkerNetwork.getInstance().sendToServer(TinkerControlPacket.DOUBLE_JUMP);
        }
      }
      wasJumping = isJumping;

      // helmet interaction
      boolean isHelmetInteracting = HELMET_INTERACT.isDown();
      if (!wasHelmetInteracting && isHelmetInteracting) {
        TooltipKey key = SafeClientAccess.getTooltipKey();
        if (InteractionHandler.startArmorInteract(event.player, EquipmentSlot.HEAD, key)) {
          TinkerNetwork.getInstance().sendToServer(TinkerControlPacket.getStartHelmetInteract(key));
        }
      }
      if (wasHelmetInteracting && !isHelmetInteracting) {
        if (InteractionHandler.stopArmorInteract(event.player, EquipmentSlot.HEAD)) {
          TinkerNetwork.getInstance().sendToServer(TinkerControlPacket.STOP_HELMET_INTERACT);
        }
      }

      // leggings interaction
      boolean isLeggingsInteract = LEGGINGS_INTERACT.isDown();
      if (!wasLeggingsInteracting && isLeggingsInteract) {
        TooltipKey key = SafeClientAccess.getTooltipKey();
        if (InteractionHandler.startArmorInteract(event.player, EquipmentSlot.LEGS, key)) {
          TinkerNetwork.getInstance().sendToServer(TinkerControlPacket.getStartLeggingsInteract(key));
        }
      }
      if (wasLeggingsInteracting && !isLeggingsInteract) {
        if (InteractionHandler.stopArmorInteract(event.player, EquipmentSlot.LEGS)) {
          TinkerNetwork.getInstance().sendToServer(TinkerControlPacket.STOP_LEGGINGS_INTERACT);
        }
      }

      wasHelmetInteracting = isHelmetInteracting;
      wasLeggingsInteracting = isLeggingsInteract;
    }
  }

@Override
  public void handleThreadsafe(Context context) {
    ServerPlayer player = context.getSender();
    if (player != null) {
      switch (this) {
        case DOUBLE_JUMP -> DoubleJumpHandler.extraJump(player);
        case ANTIGRAVITY_JUMP -> TinkerEffects.antigravity.get().antigravityJump(player);
        case START_HELMET_INTERACT, START_HELMET_INTERACT_SHIFT, START_HELMET_INTERACT_CONTROL, START_HELMET_INTERACT_ALT
          -> InteractionHandler.startArmorInteract(player, EquipmentSlot.HEAD, this.modifier);
        case STOP_HELMET_INTERACT -> InteractionHandler.stopArmorInteract(player, EquipmentSlot.HEAD);
        case START_LEGGINGS_INTERACT, START_LEGGINGS_INTERACT_SHIFT, START_LEGGINGS_INTERACT_CONTROL, START_LEGGINGS_INTERACT_ALT
          -> InteractionHandler.startArmorInteract(player, EquipmentSlot.LEGS, this.modifier);
        case STOP_LEGGINGS_INTERACT -> InteractionHandler.stopArmorInteract(player, EquipmentSlot.LEGS);
      }
    }
  }

@Override
  default boolean startInteract(IToolStackView tool, ModifierEntry modifier, Player player, EquipmentSlot slot, TooltipKey keyModifier) {
    if (!tool.isBroken() && keyModifier == TooltipKey.NORMAL && condition().matches(tool, modifier)) {
      HelmetChargingEffect.startUsingHelmet(tool, player, drawtimeMultiplier());
      return true;
    }
    return false;
  }

@Override
  default void stopInteract(IToolStackView tool, ModifierEntry modifier, Player player, EquipmentSlot slot, int chargeTime, ModifierEntry activeModifier) {
    if (chargeTime > 0 && !tool.isBroken() && condition().matches(tool, modifier)) {
      sling(tool, modifier, player, chargeTime, activeModifier);
    }
  }

public static int startUsingHelmet(IToolStackView tool, LivingEntity living, float speedFactor) {
    int time = GeneralInteractionModifierHook.startDrawing(tool, living, speedFactor);
    living.addEffect(new MobEffectInstance(TinkerModifiers.helmetCharging.get(), time + 20, 0, true, false, true));
    return time;
  }

static int startDrawing(IToolStackView tool, LivingEntity living, float speedFactor) {
    int drawtime = getDrawtime(tool, living, speedFactor);
    tool.getPersistentData().putInt(KEY_DRAWTIME, drawtime);
    return drawtime;
  }

static int getDrawtime(IToolStackView tool, LivingEntity living, float speedFactor) {
    return (int)Math.ceil(20f * speedFactor / ConditionalStatModifierHook.getModifiedStat(tool, living, ToolStats.DRAW_SPEED));
  }

static float getToolCharge(IToolStackView tool, float chargeTime) {
    if (chargeTime < 0) {
      return 0;
    }
    float charge = chargeTime / tool.getPersistentData().getInt(KEY_DRAWTIME);
    charge = (charge * charge + charge * 2) / 3;
    if (charge > 1) {
      charge = 1;
    }
    return charge;
  }

static void finishUsing(IToolStackView tool) {
    ModDataNBT persistentData = tool.getPersistentData();
    persistentData.remove(KEY_ACTIVE_MODIFIER);
    persistentData.remove(KEY_DRAWTIME);
  }

@Override
  public void sling(IToolStackView tool, ModifierEntry modifier, LivingEntity entity, int chargeTime, ModifierEntry activeModifier) {
    Level level = entity.level();
    if (!level.isClientSide && entity instanceof Player player) {
      float charge = GeneralInteractionModifierHook.getToolCharge(tool, chargeTime);
      if (charge > 0) {
        Vec3 start = player.getEyePosition(1F);
        Vec3 look = player.getLookAngle();
        Vec3 direction = start.add(look.x * RANGE, look.y * RANGE, look.z * RANGE);
        AABB bb = player.getBoundingBox().expandTowards(look.x * RANGE, look.y * RANGE, look.z * RANGE).expandTowards(1, 1, 1);

        EntityHitResult hit = ProjectileUtil.getEntityHitResult(level, player, start, direction, bb, e -> e instanceof LivingEntity);
        if (hit != null) {
          LivingEntity target = (LivingEntity)hit.getEntity();
          if (this.target.matches(target)) {
            double targetDist = start.distanceToSqr(target.getEyePosition(1F));

            // cancel if there's a block in the way
            BlockHitResult mop = ModifiableItem.blockRayTrace(level, player, ClipContext.Fluid.NONE);
            if (mop.getType() != HitResult.Type.BLOCK || targetDist < mop.getBlockPos().distToCenterSqr(start)) {
              // melee tools also do damage as a treat
              boolean didBonk = false;
              if (damageMultiplier > 0 && ToolAttackUtil.isAttackable(entity, target) && EntityInteractionModifierHook.isMelee(tool)) {
                didBonk = true;
                ModDataNBT data = tool.getPersistentData();
                data.putBoolean(IS_BONKING, true);
                InteractionHand hand = player.getUsedItemHand();
                ToolAttackContext.Builder builder = ToolAttackContext.attacker(entity).target(target).hand(hand).cooldown(Math.min(1, charge));
                if (hand == InteractionHand.MAIN_HAND) {
                  builder.applyAttributes();
                } else {
                  builder.toolAttributes(tool);
                }
                ToolAttackUtil.performAttack(tool, builder.build());
                data.remove(IS_BONKING);
              }

              // send it flying
              float inaccuracy = ModifierUtil.getInaccuracy(tool, player) * 0.0075f;
              RandomSource random = player.getRandom();
              float multiplier = charge * this.forceMultiplier.compute(modifier);
              float force = SlingForceModifierHook.modifySlingForce(tool, entity, target, modifier, SlingModule.getPower(tool, player) * multiplier, multiplier);
              Vec3 angle = Vec3.ZERO;
              if (force > 0) {
                // skip the bonk if we lack force, but the attack is fine
                angle = SlingAngleModifierHook.modifySlingAngle(tool, entity, target, modifier, force, multiplier, new Vec3(
                  (-look.x + random.nextGaussian() * inaccuracy),
                  0,
                  (-look.z + random.nextGaussian() * inaccuracy)
                ));
                target.knockback(force, angle.x, angle.z);
                if (target instanceof ServerPlayer playerMP) {
                  TinkerNetwork.getInstance().sendVanillaPacket(new ClientboundSetEntityMotionPacket(target), playerMP);
                }
                didBonk = true;
              }

              // if we dealt damage or knockback, apply bonk effects
              if (didBonk) {
                // spawn the bonk particle
                ToolAttackUtil.spawnAttackParticle(TinkerTools.bonkAttackParticle.get(), player, 0.6d);

                // modifier callbacks
                SlingLaunchModifierHook.afterSlingLaunch(tool, entity, target, modifier, force, multiplier, angle);

                // cooldowns and stuff
                level.playSound(null, player.getX(), player.getY(), player.getZ(), Sounds.BONK.getSound(), player.getSoundSource(), 1, 0.5f);
                player.causeFoodExhaustion(0.2F);
                player.getCooldowns().addCooldown(tool.getItem(), 3);
                ToolDamageUtil.damageAnimated(tool, 1, entity, entity.getUsedItemHand(), modifier.getId());
                return;
              }
            }
          }
        }
      }
      // play failure sound
      if (ModifierUtil.isActiveModifier(tool, modifier, activeModifier)) {
        level.playSound(null, player.getX(), player.getY(), player.getZ(), Sounds.BONK.getSound(), player.getSoundSource(), 1, 1f);
      }
    }
  }

